//! Generates the migration registry from the files in
//! `src/core/db/migrations/`.
//!
//! Every `migration_<version>_<name>.rs` file becomes a module and an entry in
//! `all()`, in version order. Adding a migration is just adding a file; there
//! is no central list to edit (and therefore no merge conflict beyond `HEAD`).
//!
//! The generated file lives in `OUT_DIR` and is `include!`d by `mod.rs`. The
//! modules are declared with `#[path]` because a `mod` inside an included file
//! resolves relative to the included file, not to `mod.rs`.

use std::collections::HashSet;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};

const MIGRATIONS_DIR: &str = "src/core/db/migrations";

struct Discovered {
    version: i64,
    name: String,
    module: String,
    path: PathBuf,
}

fn main() {
    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let dir = manifest_dir.join(MIGRATIONS_DIR);
    println!("cargo:rerun-if-changed={}", dir.display());

    let mut migrations = discover(&dir);
    migrations.sort_by_key(|migration| migration.version);

    let mut generated = String::new();

    for migration in &migrations {
        let path = migration
            .path
            .to_str()
            .expect("migration path must be valid UTF-8");
        generated.push_str(&format!(
            "#[path = {path:?}]\npub mod {};\n",
            migration.module
        ));
    }

    generated.push_str(
        "\n/// Every migration known to this build, in version order.\n\
         ///\n\
         /// Generated by `build.rs` from the files in this directory.\n\
         pub fn all() -> Vec<Migration> {\n    vec![\n",
    );
    for migration in &migrations {
        generated.push_str(&format!(
            "        Migration {{\n            version: {},\n            name: {:?},\n            \
             up: {}::up,\n            down: {}::DOWN,\n        }},\n",
            migration.version, migration.name, migration.module, migration.module,
        ));
    }
    generated.push_str("    ]\n}\n");

    let out = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("migrations.rs");
    fs::write(&out, generated)
        .unwrap_or_else(|err| panic!("failed to write {}: {err}", out.display()));
}

fn discover(dir: &Path) -> Vec<Discovered> {
    let entries =
        fs::read_dir(dir).unwrap_or_else(|err| panic!("failed to read {}: {err}", dir.display()));

    let mut migrations = Vec::new();
    for entry in entries {
        let path = entry
            .expect("failed to read migration directory entry")
            .path();
        if path.extension().and_then(|extension| extension.to_str()) != Some("rs") {
            continue;
        }

        let module = path
            .file_stem()
            .and_then(|stem| stem.to_str())
            .expect("migration filename must be valid UTF-8");
        let Some(rest) = module.strip_prefix("migration_") else {
            continue;
        };

        let (version, name) = rest.split_once('_').unwrap_or_else(|| {
            panic!(
                "{} must be named migration_<version>_<name>.rs",
                path.display()
            )
        });
        let version: i64 = version
            .parse()
            .unwrap_or_else(|_| panic!("{} has a non-numeric version", path.display()));
        assert!(
            version > 0,
            "{} must have a positive version",
            path.display()
        );
        validate_name(name, &path);

        migrations.push(Discovered {
            version,
            name: name.to_owned(),
            module: module.to_owned(),
            path,
        });
    }

    assert!(
        !migrations.is_empty(),
        "no migrations found in {}",
        dir.display()
    );

    let mut versions = HashSet::new();
    for migration in &migrations {
        assert!(
            versions.insert(migration.version),
            "duplicate migration version {} ({})",
            migration.version,
            migration.name
        );
    }

    migrations
}

fn validate_name(name: &str, path: &Path) {
    let valid = name.starts_with(|c: char| c.is_ascii_lowercase())
        && name
            .chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_');
    assert!(
        valid,
        "{} must use a snake_case name (lowercase letters, digits, underscores)",
        path.display()
    );
}
